class CategoryPage extends StatefulWidget {
  const CategoryPage({super.key, required this.api, required this.farm, required this.category});
  final Api api;
  final RowData farm;
  final String category;
  @override State<CategoryPage> createState() => _CategoryPageState();
}
class _CategoryPageState extends State<CategoryPage> {
  String? selected;
  String metric = 'all', status = 'all', search = '';
  final searchController = TextEditingController();
  @override void dispose() { searchController.dispose(); super.dispose(); }
  void reset() => setState(() { selected = null; metric = 'all'; status = 'all'; search = ''; searchController.clear(); });
  @override Widget build(BuildContext context) {
    final style = moduleStyles[widget.category]!;
    return DataPage(title: style.title,
      load: () async => Future.wait([
        widget.api.get('${farmPath(widget.farm)}/animals'),
        widget.api.get('${farmPath(widget.farm)}/events?category=${widget.category}'),
      ]),
      content: (c, data, reload) {
        final animals = rows(data[0]), events = rows(data[1]);
        final lookup = {for (final a in animals) '${a['id']}': a};
        final animal = lookup[selected];
        final scope = filterEvents(events, animalId: animal == null ? null : selected);
        final statuses = scope.map((e) => e['status']).whereType<String>().where((s) => s != 'all').toSet().toList()..sort();
        final effectiveStatus = statuses.contains(status) ? status : 'all';
        final visible = filterEvents(scope, metric: metric, status: effectiveStatus, search: search, animals: lookup);
        final types = kinds[widget.category]!;
        final metrics = [...types.map((k) => (k, pretty(k))), ...style.metrics.where((m) => m.$1.startsWith('method:')).map((m) => (m.$1, m.$2))];
        Future<void> add() async {
          RowData? chosen = animal;
          chosen ??= await showModalBottomSheet<RowData>(context: c, isScrollControlled: true, showDragHandle: true, builder: (_) => _AnimalChooser(animals: animals));
          if (chosen == null || !c.mounted) return;
          final initialKind = types.contains(metric) ? metric : metric.startsWith('method:') ? 'service' : null;
          if (await openPage<bool>(c, RecordForm(api: widget.api, farm: widget.farm, animal: chosen, category: widget.category, initialKind: initialKind)) == true) reload();
        }
        return ListView(padding: const EdgeInsets.fromLTRB(16, 8, 16, 30), physics: const AlwaysScrollableScrollPhysics(), children: [
          ModuleHero(style: style, count: scope.length),
          if (events.length >= 500) const Padding(padding: EdgeInsets.only(top: 12), child: Text('The server returns up to 500 recent records. Counts and filters cover this returned history only.')),
          const SizedBox(height: 14),
          DropdownButtonFormField<String>(key: ValueKey('animal-${animal == null ? 'all' : selected}'), initialValue: animal == null ? 'all' : selected, isExpanded: true,
            decoration: const InputDecoration(labelText: 'Animal scope', prefixIcon: Icon(Icons.pets)),
            items: [const DropdownMenuItem(value: 'all', child: Text('All animals')), ...animals.map((a) => DropdownMenuItem(value: '${a['id']}', child: Text('${a['name']} (${a['tag']})', overflow: TextOverflow.ellipsis)))],
            onChanged: (v) => setState(() { selected = v == 'all' ? null : v; status = 'all'; })),
          const SizedBox(height: 14),
          MetricTiles(style: style, events: scope, selected: metric, onSelect: (v) => setState(() => metric = v)),
          const SizedBox(height: 16),
          if (canRecord(widget.farm, widget.category)) ...[
            BrandButton(style.action, action: animals.isEmpty ? null : add),
            if (animals.isEmpty) const Padding(padding: EdgeInsets.symmetric(vertical: 8), child: Text('Register an animal before adding records.')),
          ],
          if (widget.category == 'reproduction' && animal != null) item('Cycle analysis', 'Review recorded cycles and estimates', icon: Icons.timeline, onTap: () => openPage(c, CyclePage(api: widget.api, farm: widget.farm, animal: animal))),
          if (widget.category == 'pregnancy') const Padding(padding: EdgeInsets.symmetric(vertical: 12), child: Text('Counts represent records, not the number of currently pregnant animals.')),
          const SizedBox(height: 18),
          Text('Record history', style: Theme.of(c).textTheme.titleLarge),
          const SizedBox(height: 8),
          TextField(controller: searchController, onChanged: (v) => setState(() => search = v), decoration: const InputDecoration(hintText: 'Search animal, type or status', prefixIcon: Icon(Icons.search))),
          const SizedBox(height: 10),
          DropdownButtonFormField<String>(key: ValueKey('metric-$metric'), initialValue: metric, isExpanded: true, decoration: const InputDecoration(labelText: 'Record type'), items: [const DropdownMenuItem(value: 'all', child: Text('All types')), ...metrics.map((m) => DropdownMenuItem(value: m.$1, child: Text(m.$2)))], onChanged: (v) => setState(() => metric = v ?? 'all')),
          const SizedBox(height: 10),
          DropdownButtonFormField<String>(key: ValueKey('status-$effectiveStatus'), initialValue: effectiveStatus, isExpanded: true, decoration: const InputDecoration(labelText: 'Status'), items: [const DropdownMenuItem(value: 'all', child: Text('All statuses')), ...statuses.map((s) => DropdownMenuItem(value: s, child: Text(pretty(s))))], onChanged: (v) => setState(() => status = v ?? 'all')),
          Row(children: [Expanded(child: Text('${visible.length} of ${scope.length} records')), TextButton.icon(onPressed: reset, icon: const Icon(Icons.clear_all), label: const Text('Clear filters'))]),
          if (visible.isEmpty) MessagePane(style.empty, icon: style.icon),
          ...visible.map((e) => eventTile(c, widget.api, widget.farm, e, lookup['${e['animal_id']}'], reload)),
        ]);
      });
  }
}

class _AnimalChooser extends StatefulWidget {
  const _AnimalChooser({required this.animals});
  final List<RowData> animals;
  @override State<_AnimalChooser> createState() => _AnimalChooserState();
}
class _AnimalChooserState extends State<_AnimalChooser> {
  String search = '';
  @override Widget build(BuildContext context) {
    final visible = widget.animals.where((a) => '${a['name']} ${a['tag']}'.toLowerCase().contains(search.trim().toLowerCase())).toList();
    return SafeArea(child: Padding(padding: EdgeInsets.only(bottom: MediaQuery.viewInsetsOf(context).bottom), child: FractionallySizedBox(heightFactor: .72, child: Column(children: [
      Text('Choose an animal', style: Theme.of(context).textTheme.titleLarge),
      Padding(padding: const EdgeInsets.all(16), child: TextField(onChanged: (v) => setState(() => search = v), decoration: const InputDecoration(hintText: 'Search name or tag', prefixIcon: Icon(Icons.search)))),
      Expanded(child: visible.isEmpty ? const MessagePane('No matching animals.', icon: Icons.pets) : ListView.builder(itemCount: visible.length, itemBuilder: (c,i) { final a = visible[i]; return ListTile(leading: const Icon(Icons.pets), title: Text('${a['name']}'), subtitle: Text('${a['tag']} • ${pretty(a['species'])}'), onTap: () => Navigator.pop(context,a)); })),
    ]))));
  }
}
